import{_ as t}from"./chunks/artisan-avatar.Bv6PR6ng.js";import{c as s,Q as o,J as n,h as i,e as a,m as l,l as c,k as h}from"./chunks/framework.WgZQdPFo.js";const x=JSON.parse('{"title":"О разработчиках","description":"История создания ОмниКрафт ЕРП, философия ремесла и контакты мастерской N. Murashkin.","frontmatter":{"title":"О разработчиках","description":"История создания ОмниКрафт ЕРП, философия ремесла и контакты мастерской N. Murashkin.","order":18},"headers":[],"relativePath":"ru/docs/about.md","filePath":"ru/docs/about.md"}'),p={name:"ru/docs/about.md"},m={id:"о-разработчиках-от-верстака-к-коду",tabindex:"-1"};function d(u,r,g,k,f,_){const e=o("DocIcon");return n(),i("div",null,[a("h1",m,[l(e,{name:"about"}),r[0]||(r[0]=c(" О разработчиках: От верстака к коду ",-1)),r[1]||(r[1]=a("a",{class:"header-anchor",href:"#о-разработчиках-от-верстака-к-коду","aria-label":'Permalink to "<DocIcon name="about" /> О разработчиках: От верстака к коду"'},"​",-1))]),r[2]||(r[2]=h('<p><strong>ОмниКрафт ЕРП</strong> — это не продукт безликой корпорации и не очередная облачная подписка от венчурного стартапа. Эта программа родилась в пыли и запахе натуральной кожи, под стук молотка и стрекот швейных машин.</p><div class="maker-profile-card"><div class="maker-avatar-wrap"><img src="'+t+'" alt="Николай Мурашкин — создатель мастерской N. Murashkin и автор ОмниКрафт ЕРП" class="maker-avatar-img"><span class="maker-avatar-badge">Мастер и архитектор</span></div><div class="maker-info"><h3 class="maker-name">Николай Мурашкин</h3><p class="maker-role">Основатель кожевенной мастерской <strong>N. Murashkin</strong> и автор платформы <strong>ОмниКрафт ЕРП</strong></p><p class="maker-quote">«Каждая строчка кода этой программы проверена сотнями часов практической работы за верстаком. Мы создавали её для себя — чтобы освободить руки от бесконечной рутины расчётов и вернуть главное: радость свободного ремесла и честный доход.»</p><div class="maker-links"><a href="https://nmurashkin.ru" target="_blank" rel="noopener noreferrer" class="maker-link-btn"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"></circle><line x1="2" y1="12" x2="22" y2="12"></line><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"></path></svg> Мастерская N. Murashkin (nmurashkin.ru) </a><a href="https://github.com/NikMurashkin/OmniCraft-ERP-Releases" target="_blank" rel="noopener noreferrer" class="maker-link-btn"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M9 19c-5 1.5-5-2.5-7-3m14 6v-3.87a3.37 3.37 0 0 0-.94-2.61c3.14-.35 6.44-1.54 6.44-7A5.44 5.44 0 0 0 20 4.77 5.07 5.07 0 0 0 19.91 1S18.73.65 16 2.48a13.38 13.38 0 0 0-7 0C6.27.65 5.09 1 5.09 1A5.07 5.07 0 0 0 5 4.77a5.44 5.44 0 0 0-1.5 3.78c0 5.42 3.3 6.61 6.44 7A3.37 3.37 0 0 0 9 18.13V22"></path></svg> Репозиторий релизов </a></div></div></div><hr><h2 id="философия-ремесла-и-кода" tabindex="-1">Философия ремесла и кода <a class="header-anchor" href="#философия-ремесла-и-кода" aria-label="Permalink to &quot;Философия ремесла и кода&quot;">​</a></h2><p>В нашей мастерской мы придерживаемся строгого правила: <strong>создавать изделия, которые будут радовать своих владельцев не одно десятилетие</strong>. Мы не гонимся за быстрой модой и одноразовыми вещами. Каждая сумка, кошелёк или аксессуар проектируется с расчётом на долгие годы службы, с использованием лучших сортов кожи и надёжной фурнитуры.</p><p>Эту же философию долговечных ценностей мы перенесли в разработку программного обеспечения. ОмниКрафт ЕРП создавалась как <strong>надёжный рабочий инструмент мастера на всю жизнь</strong>. Мы верим, что программное обеспечение для управления делом обязано быть:</p><ul><li><strong>Надёжным:</strong> Как крепкий шов вощёной нитью, программа не должна подводить в самый ответственный момент. Архитектура локальной базы данных (журналирование ВАЛ, трехуровневые резервные копии ГФС) гарантирует сохранность ваших расчётов при любых сбоях питания.</li><li><strong>Автономным и независимым:</strong> Ваши финансовые данные и клиентская база принадлежат только вам. ОмниКрафт ЕРП работает локально на вашем компьютере, не зависит от облачных серверов, не требует постоянного интернета и не отправляет коммерческие секреты на сторонние площадки.</li><li><strong>Честным:</strong> Мы против бюрократии ради галочки. Программа говорит с мастером на языке практической пользы: точной себестоимости материалов, окупаемости времени и реальной прибыли.</li></ul><hr><h2 id="почему-мы-создали-омникрафт-ерп" tabindex="-1">Почему мы создали ОмниКрафт ЕРП <a class="header-anchor" href="#почему-мы-создали-омникрафт-ерп" aria-label="Permalink to &quot;Почему мы создали ОмниКрафт ЕРП&quot;">​</a></h2><p>До появления этой платформы учёт в мастерской вёлся в разрозненных таблицах Excel, блокнотах и заметках на телефоне. Каждый раз, когда требовалось рассчитать честную цену изделия — с учётом доставки сырья, износа инструмента, расхода химии и потраченных часов труда — приходилось тратить десятки минут на рутинные вычисления или называть цену «на глаз».</p><p>Практика показала, что мастеру требуется принципиально другой подход:</p><ol><li><strong>Автоматизация вместо рутины:</strong> Программа сама рассчитывает себестоимость каждого дециметра кожи, капли клея и грамма воска по формуле скользящей средней (МАК), распределяет накладные расходы и списывает материалы со склада при сдаче заказа.</li><li><strong>Понимание отдачи от времени:</strong> Мастер видит не просто абстрактный оборот, а отдачу своего труда за каждый рабочий час и точку безубыточности мастерской.</li><li><strong>Защита от облачной кабалы:</strong> Никакого риска проснуться утром и узнать, что зарубежный сервис заблокировал аккаунт, поднял подписку втрое или отключил доступ к наработанной базе заказчиков.</li></ol><p>Так родился ОмниКрафт ЕРП — профессиональный инструмент, созданный мастерами для мастеров и предпринимателей.</p><hr><h2 id="обратная-связь-и-сообщество" tabindex="-1">Обратная связь и сообщество <a class="header-anchor" href="#обратная-связь-и-сообщество" aria-label="Permalink to &quot;Обратная связь и сообщество&quot;">​</a></h2><p>Мы продолжаем непрерывно развивать проект, опираясь на собственную практику в мастерской и потребности коллег по ремесленному сообществу.</p><p>Если вы хотите предложить инструмент под специфику своего ремесла (например, отраслевой модуль для керамики, деревообработки или ювелирного дела), сообщить об ошибке или поделиться опытом — мы всегда на связи:</p><ul><li><strong>Официальный сайт:</strong> <a href="https://omnicraft-erp.com" target="_blank" rel="noreferrer">omnicraft-erp.com</a></li><li><strong>Репозиторий релизов:</strong> <a href="https://github.com/NikMurashkin/OmniCraft-ERP-Releases" target="_blank" rel="noreferrer">OmniCraft-ERP-Releases (GitHub)</a></li><li><strong>Кожевенная мастерская N. Murashkin:</strong> <a href="https://nmurashkin.ru" target="_blank" rel="noreferrer">nmurashkin.ru</a></li></ul><hr><div class="tip custom-block"><p class="custom-block-title">Благодарность</p><p>Спасибо, что выбираете ОмниКрафт ЕРП. Наша цель — снять с ваших плеч рутину расчётов и вернуть вам самое ценное: <strong>время для творчества, близких людей и создания вещей, которые останутся в истории.</strong></p></div>',20))])}const N=s(p,[["render",d]]);export{x as __pageData,N as default};
